const body = $input.first().json.body || $input.first().json;

const tipo = body.tipo_caso || body.tipo || 'Consulta general';
const observaciones = body.observaciones || body.obs || '';
const hora = String(body.hora || '').replace(':00:00', ':00');
const clienteRegistrado = body.registrado === 'si';

const prioridades = {
  'Emergencia': 'Alta',
  'Consulta general': 'Media',
  'Vacunacion': 'Baja',
  'Vacunación': 'Baja'
};

const prioridad = body.prioridad || prioridades[tipo] || 'Media';
const disponible = true;
let accion = '';
let estado = body.estado || 'Confirmada';

if (disponible && clienteRegistrado) {
  accion = 'Confirmar cita';
  estado = 'Confirmada';
} else if (disponible && !clienteRegistrado) {
  accion = 'Registrar cliente y confirmar';
  estado = 'Confirmada';
} else if (!disponible && clienteRegistrado) {
  accion = 'Mostrar horarios alternativos';
  estado = 'Pendiente';
} else {
  accion = 'Solicitar registro del cliente';
  estado = 'Pendiente';
}

return [{
  json: {
    dueno: body.dueno || '',
    telefono: body.telefono || '',
    email: body.email || '',
    mascota: body.mascota || '',
    especie: body.especie || '',
    tipo_caso: tipo,
    prioridad,
    fecha: body.fecha || '',
    hora,
    hora_formateada: body.hora_formateada || hora,
    registrado: body.registrado || 'no',
    observaciones,
    accion_dmn: accion,
    estado,
    disponible,
    fecha_creacion: body.creado_en || new Date().toISOString()
  }
}];
